def split_row(line: str):
    """Split one CSV line into fields, handling quoted commas and quotes."""
    fields = []
    field = []
    quoted = False
    i = 0

    while i < len(line):
        char = line[i]
        if char == '"':
            if quoted and i + 1 < len(line) and line[i + 1] == '"':
                field.append('"')
                i += 1
            else:
                quoted = not quoted
        elif char == ',' and not quoted:
            fields.append(''.join(field))
            field = []
        else:
            field.append(char)
        i += 1

    fields.append(''.join(field))
    return fields
